func prevMonthPath(year, month int) string {
	if month == 1 {
		return fmt.Sprintf("/calendar/%d/12", year-1)
	}
	return fmt.Sprintf("/calendar/%d/%d", year, month-1)
}

func nextMonthPath(year, month int) string {
	if month == 12 {
		return fmt.Sprintf("/calendar/%d/1", year+1)
	}
	return fmt.Sprintf("/calendar/%d/%d", year, month+1)
}

func monthName(month int) string {
	return time.Month(month).String()
}

func dayCellClass(day DayCell) string {
	cls := "day-cell"
	if !day.IsCurrentMonth {
		cls += " other-month"
	}
	if day.IsToday {
		cls += " today"
	}
	return cls
}

// formatEventTime renders an event's start in the user's calendar zone, the
// zone the views place it in.
func formatEventTime(ctx context.Context, unix int64) string {
	return time.Unix(unix, 0).In(calendarNow(ctx).Location()).Format("15:04")
}

func formatEventDate(ctx context.Context, unix int64) string {
	if unix == 0 {
		return "-"
	}
	return time.Unix(unix, 0).In(calendarNow(ctx).Location()).Format("Jan 2, 2006")
}

// formatEventListDate formats an event's start date for lists. An all-day
// event is a UTC calendar date, so no zone shifts it.
func formatEventListDate(ctx context.Context, e *bongov1.Event) string {
	if e.AllDay {
		return icalevent.AllDayDate(e.StartTime).Format("Jan 2, 2006")
	}
	return formatEventDate(ctx, e.StartTime)
}

func truncateTitle(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	return s[:maxLen-1] + "..."
}

// eventAttendeesValue is the attendees input's initial text: one "Name <addr>"
// entry per attendee, in the form parseAttendees reads back.
func eventAttendeesValue(e *bongov1.Event) string {
	if e == nil {
		return ""
	}
	parts := make([]string, 0, len(e.Attendees))
	for _, a := range e.Attendees {
		parts = append(parts, attendeeEntry(a))
	}
	return strings.Join(parts, ", ")
}

// attendeeEntry is one "Name <addr>" entry. It is built by hand because
// mail.Address.String would RFC 2047-encode a non-ASCII name, and the field
// is plain text the user reads and edits. A name holding an RFC 5322 special
// is quoted, with the quote and backslash escaped, so the list parser reads it
// back unchanged.
func attendeeEntry(a *bongov1.Attendee) string {
	if a.Name == "" {
		return a.Address
	}
	name := a.Name
	if strings.ContainsAny(name, "()<>[]:;@\\,.\"") {
		name = `"` + strings.NewReplacer(`\`, `\\`, `"`, `\"`).Replace(name) + `"`
	}
	return name + " <" + a.Address + ">"
}

// attendeeLabel is the name an attendee is listed under.
func attendeeLabel(a *bongov1.Attendee) string {
	if a.Name != "" {
		return a.Name + " <" + a.Address + ">"
	}
	return a.Address
}

// attendeeStatusClass is the CSS modifier for an attendee's PARTSTAT. An
// unset or unknown value reads as needs-action.
func attendeeStatusClass(partstat string) string {
	switch strings.ToUpper(partstat) {
	case "ACCEPTED":
		return "accepted"
	case "DECLINED":
		return "declined"
	case "TENTATIVE":
		return "tentative"
	case "DELEGATED":
		return "delegated"
	}
	return "needs-action"
}

// attendeeStatusKey is the message ID of the badge text for a PARTSTAT.
func attendeeStatusKey(partstat string) string {
	switch attendeeStatusClass(partstat) {
	case "accepted":
		return "calendar.partstat.accepted"
	case "declined":
		return "calendar.partstat.declined"
	case "tentative":
		return "calendar.partstat.tentative"
	case "delegated":
		return "calendar.partstat.delegated"
	}
	return "calendar.partstat.needsAction"
}

